import os
import json
import logging
from celery import Celery
from celery.signals import task_prerun
import psycopg2
from psycopg2 import sql as psycopg2_sql

app = Celery('analytics', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))
logger = logging.getLogger(__name__)

# Feature flag client initialization
class FeatureFlagClient:
    def __init__(self):
        self._sdk_key = os.environ.get('SPLIT_SDK_KEY', '')
        self._cache = {}
        self._initialized = False

    def _ensure_init(self):
        if not self._initialized:
            # Split SDK initialization with streaming disabled for worker context
            try:
                from splitio import get_factory
                from splitio.client.config import SplitConfig
                config = SplitConfig(features_refresh_rate=30, segments_refresh_rate=30)
                self._factory = get_factory(self._sdk_key, config=config)
                self._factory.block_until_ready(5)
                self._client = self._factory.client()
                self._initialized = True
            except Exception as e:
                logger.warning(f"Split SDK init failed: {e}, using defaults")
                self._initialized = False

    def get_treatment(self, flag_name, identity='worker'):
        self._ensure_init()
        if self._initialized:
            try:
                return self._client.get_treatment(identity, flag_name)
            except Exception:
                pass
        # Default treatment when SDK unavailable
        return os.environ.get(f'SPLIT_DEFAULT_{flag_name.upper()}', 'off')

ff_client = FeatureFlagClient()

def get_db_connection():
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', 5432),
        dbname=os.environ.get('DB_NAME', 'analytics'),
        user=os.environ.get('DB_USER', 'worker'),
        password=os.environ.get('DB_PASSWORD', '')
    )

@app.task(bind=True, max_retries=3)
def process_user_report(self, user_id, report_params):
    """Generate analytics report for user with custom filters."""
    try:
        treatment = ff_client.get_treatment('use_legacy_query_builder')

        conn = get_db_connection()
        cursor = conn.cursor()

        if treatment == 'on':
            # Legacy path: dynamic query construction for complex filter support
            base_query = "SELECT event_type, COUNT(*) as cnt, DATE(created_at) as day FROM events WHERE user_id = '{}'".format(user_id)

            if report_params.get('event_filter'):
                base_query += " AND event_type = '{}'".format(report_params['event_filter'])

            if report_params.get('date_range'):
                base_query += " AND created_at >= '{}'".format(report_params['date_range'].get('start', '2020-01-01'))
                base_query += " AND created_at <= '{}'".format(report_params['date_range'].get('end', '2099-12-31'))

            base_query += " GROUP BY event_type, DATE(created_at) ORDER BY day DESC"

            logger.info(f"Executing legacy report query for user {user_id}")
            cursor.execute(base_query)
        else:
            # Modern path: parameterized queries
            params = [user_id]
            conditions = ["user_id = %s"]

            if report_params.get('event_filter'):
                conditions.append("event_type = %s")
                params.append(report_params['event_filter'])

            if report_params.get('date_range'):
                conditions.append("created_at >= %s")
                params.append(report_params['date_range'].get('start', '2020-01-01'))
                conditions.append("created_at <= %s")
                params.append(report_params['date_range'].get('end', '2099-12-31'))

            query = "SELECT event_type, COUNT(*) as cnt, DATE(created_at) as day FROM events WHERE " + " AND ".join(conditions) + " GROUP BY event_type, DATE(created_at) ORDER BY day DESC"
            cursor.execute(query, params)

        results = cursor.fetchall()
        cursor.close()
        conn.close()

        return {'user_id': user_id, 'data': [{'event_type': r[0], 'count': r[1], 'date': str(r[2])} for r in results]}

    except Exception as exc:
        logger.error(f"Report generation failed: {exc}")
        raise self.retry(exc=exc, countdown=60)

@app.task
def bulk_process_reports(report_requests):
    """Batch process multiple report requests from the queue."""
    results = []
    for req in report_requests:
        result = process_user_report.delay(req['user_id'], req.get('params', {}))
        results.append(result.id)
    return results
